#include <iostream>

class Point {
private:
    int xCoordinate{0};
    int yCoordinate{0};
    bool valid{false};

public:
    Point() = default;
    Point(int x, int y) : xCoordinate(x), yCoordinate(y), valid(true) {}

    friend std::istream& operator>>(std::istream& in, Point& p);
    friend std::ostream& operator<<(std::ostream& out, const Point& p);
};

std::istream& operator>>(std::istream& in, Point& p) {
    char leftParen = 0, comma = 0, rightParen = 0;
    int x = 0, y = 0;

    // Expected format: (x, y)
    if (in >> leftParen && leftParen == '(' &&
        in >> x &&
        in >> comma && comma == ',' &&
        in >> y &&
        in >> rightParen && rightParen == ')') {
        p.xCoordinate = x;
        p.yCoordinate = y;
        p.valid = true;
    } else {
        in.setstate(std::ios_base::failbit);
        p.valid = false;
    }
    return in;
}

std::ostream& operator<<(std::ostream& out, const Point& p) {
    if (!p.valid) {
        out << "[Invalid Point]";
        return out;
    }
    out << '(' << p.xCoordinate << ", " << p.yCoordinate << ')';
    return out;
}

int main() {
    Point pt;
    if (std::cin >> pt) {
        std::cout << "Successfully read: " << pt << '\n';
    } else {
        std::cout << "Input error encountered.\n";
    }
    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    // Part 1: Base manipulators demonstration (ASCII 65 = 'A', 66 = 'B')
    for (int code = 65; code <= 66; ++code) {
        std::cout << "Char: " << static_cast<char>(code)
                  << " | Dec: " << std::dec << code
                  << " | Oct: " << std::oct << code
                  << " | Hex: " << std::hex << code << '\n';
    }

    // Reset stream to decimal
    std::cout << std::dec;

    // Part 2: get vs getline difference
    char buf1[10];
    char buf2[10];

    // Read up to ',' using get: leaves ',' in stream
    std::cin.get(buf1, 10, ',');
    char nextCharAfterGet = static_cast<char>(std::cin.peek());

    // Discard the comma manually
    std::cin.ignore(1);

    // Read up to '\n' using getline: extracts and discards '\n'
    std::cin.getline(buf2, 10);

    std::cout << "buf1: " << buf1 << " (peek next: '" << nextCharAfterGet << "')\n";
    std::cout << "buf2: " << buf2 << '\n';
    return 0;
}
